/*
 * A207618  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A207619; see the Formula section.
 * https://oeis.org/A207618
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) is the nth coefficient of the polynomials u(n,x) (see the
 *            definition in the OEIS entry). The polynomials are generated by
 *            the recurrences u(n,x) = u(n‑1,x) + v(n‑1,x) v(n,x) = x*u(n‑1,x)
 *            + 2x*v(n‑1,x) + 1 with u(1,x)=1, v(1,x)=1. The sequence gives
 *            the flattened list of the polynomial coeffi...
 * Range:     u8 n <= 32, u16 n <= 59, u32 n <= 59, u64 n <= 59, u128 n <= 59,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  #include for required types  */
#include <stdint.h>
#include <stdlib.h>

/*  static state for memoisation  */
static seq_t *u = NULL;        /* coefficients of current u(r,x)   */
static seq_t *v = NULL;        /* coefficients of current v(r,x)   */
static idx_t  curr_row = 0;    /* number of the currently stored row */

/*  grow the stored polynomials to at least the given target row  */
static void grow_to_row(idx_t target)
{
    while (curr_row < target)
    {
        idx_t old_u_len = (curr_row <= 2 ? 1 : curr_row - 1);   /* length of u(r,x) */
        idx_t old_v_len = curr_row;                             /* length of v(r,x) */
        idx_t new_row    = curr_row + 1;                        /* next row number */
        idx_t new_u_len  = (new_row <= 2 ? 1 : new_row - 1);    /* length of u(next) */
        idx_t new_v_len  = new_row;                            /* length of v(next) */

        seq_t *new_u = (seq_t*)malloc((size_t)new_u_len * sizeof(seq_t));
        seq_t *new_v = (seq_t*)malloc((size_t)new_v_len * sizeof(seq_t));

        /*  compute u(next)  */
        for (idx_t i = 0; i < new_u_len; ++i)
        {
            if (i < old_u_len)
                new_u[i] = u[i] + v[i];
            else
                new_u[i] = v[i];
        }

        /*  compute v(next)  */
        new_v[0] = (seq_t)1;
        for (idx_t i = 1; i < new_v_len; ++i)
        {
            seq_t part1 = (i-1 < old_u_len) ? u[i-1] : (seq_t)0;
            seq_t part2 = v[i-1] << 1;   /* 2 * v[i-1]  */
            new_v[i] = part1 + part2;
        }

        free(u);
        free(v);
        u = new_u;
        v = new_v;
        curr_row = new_row;
    }
}

/*  public function  */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;       /* offset is 1, so n=0 is not used */

    /*  initialise on first call  */
    if (curr_row == 0)
    {
        curr_row = 1;
        u = (seq_t*)malloc(sizeof(seq_t));
        v = (seq_t*)malloc(sizeof(seq_t));
        u[0] = v[0] = (seq_t)1;
    }

    /*  determine the row r that contains index n
        and the element offset inside that row  */
    idx_t r = 1;
    idx_t row_len = 1;                /* length of row r */
    idx_t remaining = n;
    while (remaining > row_len)
    {
        remaining -= row_len;
        ++r;
        row_len = (r <= 2 ? 1 : r - 1);
    }
    idx_t offset = remaining - 1;      /* 0‑based within the row */

    /*  ensure we have computed up to row r  */
    grow_to_row(r);

    /*  fetch and return the desired coefficient  */
    return u[offset];
}
